# extra per-Ekādaśī data: teller, characters, fruits (phala), custom
M={
'papamocani':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what the sage Lomaśa told King Māndhātā.',chars=[('🧘','Medhāvī','Young sage, son of Cyavana, doing penance in the Caitraratha forest.'),('💃','Mañjughoṣā','The apsarā sent to distract him; cursed, then freed.'),('👴','Cyavana','Medhāvī’s father, who prescribes the vow for both.'),('🏹','Kāma','The god of love, behind the distraction.')],fruits='The māhātmya says the fast destroys even grave sins and frees from the state of a ghost.',custom='As the last Ekādaśī of the old year (northern reckoning), many treat it as a clearing of the year’s faults before Ugādi.'),
'kamada':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what the sage Vasiṣṭha told King Dilīpa.',chars=[('🎶','Lalita','A gandharva singer at the court of the nāga king Puṇḍarīka.'),('💗','Lalitā','His devoted wife, who gives him her merit.'),('👑','Puṇḍarīka','The nāga king who curses Lalita for singing out of tune.'),('🧘','Śṛṅgī','The sage who teaches Lalitā the vow.')],fruits='It is said to grant every wish and free from even a rākṣasa’s state.',custom='As the first Ekādaśī of the new year, many begin their year’s Ekādaśī vows on it.'),
'varuthini':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Bhaviṣyottara and Padma Purāṇa tellings).',chars=[('👑','Māndhātā','A righteous king doing penance by the Narmadā.'),('🐻','The bear','Which seizes his foot as he meditates.'),('🌀','Viṣṇu','Who kills the bear with his discus and prescribes the vow.'),('🐗','Varāha','The form of Viṣṇu worshipped at Mathurā for healing.')],fruits='Armour against misfortune; good fortune for women; heaven for Māndhātā and others like Dhundhumāra.',custom='Its māhātmya praises gifts on this day, above all the gift of learning and of food.'),
'mohini':dict(teller='Vasiṣṭha tells Rāma, grieving for Sītā; Kṛṣṇa retells it to Yudhiṣṭhira.',chars=[('💰','Dhanapāla','A pious merchant of Bhadrāvatī.'),('🍷','Dhṛṣṭabuddhi','His youngest son, ruined by vice.'),('🧘','Kauṇḍinya','The sage who gives him the way out.'),('🏺','Mohinī','Viṣṇu’s enchantress form, who gave the gods the nectar.')],fruits='It is said to free from the net of delusion and grave sins.',custom='The day is also remembered for Viṣṇu’s Mohinī form at the churning of the ocean; see our <a href="/festivals/pradosha/nilakantha/">Nīlakaṇṭha</a> article.'),
'apara':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Brahmāṇḍa and Padma Purāṇa tellings).',chars=[('👑','Mahīdhvaja','A good king murdered by his brother.'),('🗡️','Vajradhvaja','The jealous younger brother.'),('👻','The ghost','Mahīdhvaja’s restless spirit in the pīpal.'),('🧘','Dhaumya','The sage who gives his merit to free him.')],fruits='Its merit is called boundless (aparā); it is said to free from the sins of false witness, slander and the like.',custom='Some keep it in memory of family members who died suddenly or unjustly.'),
'nirjala':dict(teller='Vyāsa tells Bhīma, who asks how he can gain the merit of Ekādaśī without fasting all year.',chars=[('💪','Bhīma','The strongest Pāṇḍava, unable to bear hunger.'),('🧘','Vyāsa','The sage who prescribes one waterless fast.'),('👑','Yudhiṣṭhira','Who, with the others, keeps every Ekādaśī.'),('💧','Water','Given to others, though not drunk, on this day.')],fruits='One waterless fast is said to equal all twenty-four Ekādaśīs of the year.',custom='Giving water pots, fans, umbrellas and cool drinks to others is a traditional part of the day. The waterless fast is genuinely risky in summer heat; the old, unwell and pregnant should not attempt it.'),
'yogini':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what Mārkaṇḍeya told Hemamālī.',chars=[('🌸','Hemamālī','Kubera’s yakṣa gardener who forgets the flowers.'),('💗','His wife','Viśālākṣī in some tellings, with whom he stayed home.'),('💰','Kubera','The god of wealth, a devotee of Śiva, who curses him.'),('🧘','Mārkaṇḍeya','The sage who heals him through the vow.')],fruits='It is said to cure disease, above all skin disease, and to equal the merit of feeding many brahmins.',custom='Kept by those praying for recovery from illness; it is also the last Ekādaśī before Viṣṇu’s four-month sleep.'),
'devashayani':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what Brahmā told Nārada (Bhaviṣyottara Purāṇa).',chars=[('👑','Māndhātā','The good king whose land has no rain for three years.'),('🧘','Aṅgiras','The sage who advises the vow.'),('🐍','Śeṣa','The serpent on whom Viṣṇu sleeps.'),('🌧️','The rains','Which return when the vow is kept.')],fruits='Rain and prosperity for the land; the start of Cāturmāsya’s merit.',custom='It opens Cāturmāsya; in Maharashtra it is the great Āṣāḍhī Vārī to Paṇḍharpūr. See our <a href="/festivals/guru-purnima/chaturmasya/">Cāturmāsya</a> article.'),
'kamika':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what Brahmā told Nārada; the māhātmya is a praise without a single narrative.',chars=[('🎶','Nārada','Who asks Brahmā about this Ekādaśī.'),('🪷','Brahmā','Who praises its worship.'),('🌿','Tulasī','Whose worship the day honours above gold.'),('🪔','The lamp','A ghee lamp offered to Viṣṇu through the night.')],fruits='The merit of great sacrifices and pilgrimages; release for the ancestors through the lamp offered.',custom='Worship Viṣṇu with tulasī leaves and keep a ghee lamp burning; see our <a href="/festivals/kartika/tulasi/">Tulasī</a> article.'),
'shravana-putrada':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Bhaviṣyottara Purāṇa).',chars=[('👑','Mahījit','The childless king of Māhiṣmatī.'),('🧘','Lomaśa','The sage who sees the cause in a past life.'),('🐄','The thirsty cow','Driven from water in the king’s past life.'),('🧑‍🤝‍🧑','The people','Who keep the vow for their king.')],fruits='The blessing of a child; also called Pavitrā, “the pure”.',custom='Couples praying for children keep it; today many pray for children of either sex.'),
'aja':dict(teller='Kṛṣṇa tells Yudhiṣṭhira.',chars=[('👑','Hariścandra','The king who never lied.'),('💗','Taramatī','His queen, sold into service.'),('👦','Rohitāśva','His son, who dies and is restored.'),('🧘','Gautama','The sage who advises the vow.')],fruits='The end of long suffering; restoration of what was lost.',custom='It falls near Janmāṣṭamī; see our <a href="/festivals/krishna-janmashtami/">Janmāṣṭamī</a> article.'),
'parivartini':dict(teller='Kṛṣṇa tells Yudhiṣṭhira the story of Vāmana and Bali.',chars=[('👑','Bali','The generous demon king who rules the three worlds.'),('👦','Vāmana','Viṣṇu as a dwarf boy asking for three steps.'),('🧘','Śukra','Bali’s teacher, who warns him.'),('🐍','Viṣṇu asleep','Who turns on his side this day.')],fruits='It is said to grant the merit of a great sacrifice and Vāmana’s grace.',custom='Vāmana Jayantī is often kept on the next day, Dvādaśī; see our <a href="/vishnu/dashavatara/">Daśāvatāra</a> series.'),
'indira':dict(teller='Kṛṣṇa tells Yudhiṣṭhira.',chars=[('👑','Indrasena','King of Māhiṣmatī.'),('🎶','Nārada','Who brings word from the realm of Yama.'),('👴','The father','Held back in Yama’s realm by a broken vow.'),('⚖️','Yama','Lord of the dead.')],fruits='Release for the ancestors; the father raised to heaven.',custom='It falls in Pitṛ Pakṣa and is kept with offerings for departed parents; see our <a href="/festivals/pitru-paksha/">Pitṛ Pakṣa</a> series.'),
'papankusha':dict(teller='Kṛṣṇa tells Yudhiṣṭhira.',chars=[('🏹','Krodhana','A cruel hunter of the Vindhyas.'),('🧘','Aṅgiras','The sage he begs for help.'),('⚖️','Yama’s messengers','Whom he fears at the end.'),('🐘','The goad','The aṅkuśa that gives the day its name.')],fruits='Release from grave sin even late in life.',custom='It falls just after Vijayadaśamī; see our <a href="/festivals/navaratri/">Navarātri</a> series.'),
'rama':dict(teller='Kṛṣṇa tells Yudhiṣṭhira.',chars=[('👑','Mucukunda','A king so strict that all his kingdom kept Ekādaśī.'),('💗','Candrabhāgā','His daughter, a lifelong keeper of the vow.'),('🤴','Śobhana','Her frail husband, who dies keeping it.'),('🏰','The city on Mandara','Where Śobhana is reborn as king.')],fruits='Wealth and good fortune (Ramā is Lakṣmī); a stable heavenly state.',custom='It comes just before Dīpāvalī; see our <a href="/festivals/deepavali/">Dīpāvalī</a> article. The frail and the sick are excused from fasting.'),
'prabodhini':dict(teller='Brahmā tells Nārada (Skanda Purāṇa tellings); widely kept as Viṣṇu’s waking.',chars=[('🐍','Viṣṇu','Who wakes from his four-month sleep.'),('🌿','Tulasī','Who marries him as the śālagrāma.'),('🐚','The conch','Blown to wake him.'),('🙏','Devotees','Who end their Cāturmāsya vows.')],fruits='It is praised as equal to great sacrifices and pilgrimages; vows completed bear fruit.',custom='Tulasī Vivāha follows; see our <a href="/festivals/kartika/prabodhini-tulasi-vivaha/">Prabodhinī and Tulasī Vivāha</a>.'),
'utpanna':dict(teller='Kṛṣṇa tells Arjuna (and Yudhiṣṭhira) the birth of Ekādaśī.',chars=[('👹','Mura','The demon who drove out the gods.'),('🌀','Viṣṇu','Who fought him, then rested in a cave.'),('⚔️','Ekādaśī','The goddess born from Viṣṇu’s body.'),('⛰️','Badarikāśrama','The cave where Viṣṇu slept.')],fruits='It is the source of all Ekādaśīs; starting the vow on it is especially praised.',custom='Many begin a lifelong Ekādaśī vow on this day; see '+'Part 1'+'.'),
'mokshada':dict(teller='Kṛṣṇa tells Yudhiṣṭhira.',chars=[('👑','Vaikhānasa','The king who dreams of his father in hell.'),('🧘','Parvata','The sage who reveals the father’s fault.'),('👴','The father','Released by his son’s merit.'),('🚪','Vaikuṇṭha dvāra','The northern gate opened in temples.')],fruits='Liberation (mokṣa), for oneself and one’s ancestors.',custom='Kept as Vaikuṇṭha Ekādaśī and Gītā Jayantī; see our <a href="/festivals/vaikuntha-ekadashi/">Vaikuṇṭha Ekādaśī</a> article.'),
'saphala':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Bhaviṣyottara Purāṇa).',chars=[('👑','Mahiṣmān','The king of Campāvatī who banishes his son.'),('😈','Lumpaka','The wicked prince, later reformed.'),('🌳','The banyan','The old tree, dear to Viṣṇu, where he lives.'),('🐎','The horse','Sent to carry him home.')],fruits='Success (saphala) in all things; it is praised above great sacrifices.',custom='Offering fruits to Viṣṇu is customary, after Lumpaka’s offering.'),
'pausha-putrada':dict(teller='Kṛṣṇa tells Yudhiṣṭhira.',chars=[('👑','Suketumān','The childless king of Bhadrāvatī.'),('💗','Śaibyā','His queen.'),('🧘','The Viśvadevas','Sages at the lake who advise the vow.'),('👶','The son','Born and grown into a worthy king.')],fruits='The blessing of a child and continuity of the family’s rites.',custom='It falls in winter near Saṅkrānti; see our <a href="/festivals/makara-sankranti/">Saṅkrānti</a> article.'),
'shattila':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what Pulastya told Dālbhya.',chars=[('👩','The brahmin woman','Who fasted all her life but never gave food.'),('🙏','Viṣṇu as beggar','To whom she gave a lump of clay.'),('🏠','The empty house','Her reward in heaven.'),('🌸','Celestial women','Who teach her the sesame vow.')],fruits='Food and plenty; the sesame gifts are said to bring as many years in heaven as there are seeds.',custom='Sesame is used six ways: bath paste, bath, homa, water offering, food and gift.'),
'jaya':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Bhaviṣyottara Purāṇa).',chars=[('🎶','Mālyavān','A gandharva singer.'),('💃','Puṣpavatī','A celestial dancer.'),('👑','Indra','Who curses them for losing the rhythm.'),('🏔️','The Himālaya','Where they suffer as piśācas.')],fruits='Release from the state of ghosts and goblins; also called Bhaimī Ekādaśī.',custom='It falls in Māgha, the bathing month at Prayāga.'),
'vijaya':dict(teller='Kṛṣṇa tells Yudhiṣṭhira what Brahmā told Nārada.',chars=[('🏹','Rāma','At the ocean shore before Laṅkā.'),('🛡️','Lakṣmaṇa','Who leads him to the sage.'),('🧘','Bakadālbhya','The sage who prescribes the vow.'),('🏺','The kalaśa','Worshipped in the vow.')],fruits='Victory (vijaya) in hard undertakings.',custom='It falls near Mahā Śivarātri; see our <a href="/festivals/maha-shivaratri/">Śivarātri</a> article.'),
'amalaki':dict(teller='Vasiṣṭha tells King Māndhātā, as Kṛṣṇa relates to Yudhiṣṭhira.',chars=[('👑','Caitraratha','King of Vaidiśa, whose city keeps the vow.'),('🏹','The hunter','Who watches the night worship.'),('👑','Vasuratha','The hunter reborn as a king.'),('🌳','The āmalakī','The gooseberry tree dear to Viṣṇu.')],fruits='Protection from enemies; the merit of a thousand cows given.',custom='Worship at an āmalakī tree, watering and circling it; it falls just before Holī.'),
'padmini':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Padma Purāṇa).',chars=[('👑','Kṛtavīrya','The childless king.'),('💗','Padminī','His queen, who keeps the vow.'),('🧘','Anasūyā','Atri’s wife, who advises her.'),('💪','Kārtavīrya Arjuna','The son born, later the captor of Rāvaṇa.')],fruits='A mighty child; the merit of the rare leap month.',custom='Kept only in leap years (Adhika Māsa).'),
'parama':dict(teller='Kṛṣṇa tells Yudhiṣṭhira (Padma Purāṇa).',chars=[('🧑','Sumedhā','A poor, generous brahmin.'),('💗','Pavitrā','His wife, who persuades him to stay.'),('🧘','Kauṇḍinya','The sage who teaches the vow.'),('💰','Kubera','Who brings wealth by Viṣṇu’s command.')],fruits='Release from poverty; prosperity used for others.',custom='Kept only in leap years; its full vow runs five days (Pañcarātra) in some tellings.')}
